const links = phi.query("a", { fields: ["href"], limit: 400 });
const careers = links.items.filter(i => i.href && /career|job/i.test(i.href));
const nav = phi.observe({ maxElements: 60 });
return { careers, navNodes: nav.nodes.map(n => n.role + " " + (n.name||"")).slice(0, 60), total: links.total };

const a = phi.fill(1, "Human Resources");
phi.sleep(800);
const afterKw = phi.observe({ viewportOnly: true, maxElements: 40 });
const b = phi.fill(2, "Miami");
phi.sleep(1200);
const afterLoc = phi.observe({ viewportOnly: true, maxElements: 40 });
return {
  kw: { changed: a.changed },
  loc: { changed: b.changed },
  nodes: afterLoc.nodes.map(n => n.ref + " | " + n.role + " | " + (n.name || "") + (n.value ? " = " + n.value : ""))
};

const o = phi.observe({ maxElements: 40 });
const nodes = o.nodes.map(n => n.ref + " | " + n.role + " | " + (n.name||"") + (n.value ? " = " + n.value : ""));
const kw = phi.query("input", { fields: ["id","value","placeholder"], limit: 8 });
return { nodes: nodes.slice(0, 30), kw };

const f = phi.fill("input[placeholder='City or Zip Code']", "Miami, FL");
phi.sleep(1500);
const o = phi.observe({ maxElements: 60 });
const opts = o.nodes.filter(n => n.role === "option" || /Miami|FL/i.test(n.name||"")).map(n => n.ref + " | " + n.role + " | " + (n.name||""));
return { fill: f && f.changed, opts };

const c = phi.click(18);
phi.sleep(1200);
const o = phi.observe({ maxElements: 60 });
const inputs = phi.query("input[placeholder='City or Zip Code'], input[placeholder='Job title, skill, or keyword']", { fields: ["id","value"], limit: 6 });
return { click: { url: c && c.url, navigated: c && c.navigated, changed: c && c.changed }, inputs, buttons: o.nodes.filter(n => n.role === "button" && /Search jobs/i.test(n.name||"")).map(n => n.ref + " | " + n.name) };

const t = phi.text();
const o = phi.observe({ maxElements: 80 });
const heads = o.nodes.filter(n=>/heading/.test(n.role)).map(n=>n.ref+" | "+n.name);
return { len: t.length, tail: t.slice(1000, 3000), heads };

