const q = phi.query("a[href*='/job/'], a[href*='job-detail']", { fields: ["href"], limit: 40 });
const t = phi.text();
const start = t.indexOf("results for");
const end = t.indexOf("Want to receive job alerts");
const listing = t.slice(start, end > 0 ? end : start + 1500);
phi.keep("miami_hr", {
  url: "https://corporate.target.com/careers/job-search?currentPage=1&query=Human%20Resources&lat=25.76417&lon=-80.18459&location=Miami%2C%20FL",
  query: "Human Resources",
  location: "Miami, FL (Within 25 Miles)",
  count: "6 results",
  listing
});
return { linkTotal: q.total, links: q.items.slice(0, 10), listingLen: listing.length };

